changeSet.sql:
INSERT INTO country (iso, name, eu_member, legal_basis, retention_months)
VALUES ('MT', 'Malte', TRUE,
        'Règlement S.L. 373.01 sur la prévention du blanchiment de capitaux et du financement du terrorisme (PMLFTR) et procédures d''application de la FIAU : personnes politiquement exposées, membres de leur famille et proches associés, douze mois après la fin des fonctions', 12);

INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Malte – Chambre des représentants', 'Députés en fonction (15e législature), députés de la législature précédente terminée depuis moins de 12 mois et président de la Chambre, d''après parlament.mt (catégorie MT-b)', 'mt_pep_parliament', 'PEP', 'https://parlament.mt/en/15th-leg/political-groups/', 'mt-pep-parliament', 'D:/test parser 2/plugins/swiftcheck-aml-mt-pep-parliament-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'WEB_PAGE', NULL, '{"currentUrl": "https://parlament.mt/en/15th-leg/political-groups/", "previousUrl": "https://parlament.mt/en/14th-leg/political-groups/", "speakerUrl": "https://parlament.mt/en/15th-leg/political-groups/speaker-abela-carmelo/", "monthsAfterEnd": "12"}', 168, 12, 'Site officiel du Parlement de Malte : citer la source', 'Parlament ta'' Malta, parlament.mt', 'Trois pages (1 seconde entre les appels) : groupes parlementaires de la 15e législature (79 députés) et de la 14e (79, dont 56 réélus), fiche du président de la Chambre. Identifiant = adresse de la fiche, stable d''une législature à l''autre : une personne réélue n''est écrite qu''une fois. Fonctions de la liste (Premier ministre, whips, chef de l''opposition) en description ; le Premier ministre reçoit un poste distinct. Ni naissance ni date de fin (fiches individuelles non lues). La 14e législature est gardée tant que son année de fin (2026) est celle de la fenêtre de rétention ou plus récente. Le site est derrière Cloudflare et répond par moments 403 : le parser échoue alors avec le code HTTP.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Les 79 députés de la 15e législature et les 79 de la 14e (terminée en 2026), par leur nom, avec groupe et fonction au Parlement.', 'Ni naissance ni date de fin de mandat ; législature 2022-2026 gardée à l''année près.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'MT-b' AND f.label IN ('Député de la Chambre des représentants', 'Ancien député de la Chambre des représentants') AND p.dataset_name = 'mt_pep_parliament';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Le président de la Chambre en fonction (élu le 20/06/2026).', 'Ses prédécesseurs ne sont pas couverts.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'MT-b' AND f.label = 'Président de la Chambre des représentants' AND p.dataset_name = 'mt_pep_parliament';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', FALSE, 'Le Premier ministre Robert Abela (poste distinct) ; les autres ministres figurent comme députés, sans leur fonction ministérielle.', 'Ministres et secrétaires parlementaires non identifiés comme tels : gov.mt est protégé par Cloudflare.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'MT-a' AND f.label = 'Premier ministre et ministres' AND p.dataset_name = 'mt_pep_parliament';

INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Malte – Président et Auditeur général', 'Présidente de la République (president.gov.mt) et Auditeur général avec son adjoint (nao.gov.mt) (catégories MT-a et MT-e)', 'mt_pep_institutions', 'PEP', 'https://nao.gov.mt/about-us/senior-officials/', 'mt-pep-institutions', 'D:/test parser 2/plugins/swiftcheck-aml-mt-pep-institutions-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'WEB_PAGE', NULL, '{"presidentUrl": "https://president.gov.mt/biography/", "auditUrl": "https://nao.gov.mt/about-us/senior-officials/"}', 168, 12, 'Sites officiels : citer la source', 'Office of the President of Malta ; National Audit Office, Malta', 'Deux pages : la biographie de la présidente Myriam Spiteri Debono et la liste des hauts responsables du NAO (Auditeur général Charles Deguara, adjoint Noel Camilleri ; les deux adjoints à l''Auditeur général ne sont pas repris). Ni naissance ni dates de fonction. Les deux sites sont derrière Cloudflare et répondent par moments 403 : le parser échoue alors avec le code HTTP.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'La présidente de la République en exercice.', 'Les anciens présidents ne sont pas couverts ; pas de naissance.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'MT-a' AND f.label = 'Président de la République' AND p.dataset_name = 'mt_pep_institutions';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'L''Auditeur général et son adjoint en fonction.', 'Les anciens titulaires ne sont pas couverts ; pas de naissance.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'MT-e' AND f.label = 'Auditeur général et adjoint' AND p.dataset_name = 'mt_pep_institutions';
